export default function(params) {
  const sigma = params.sigma ?? 10;
  const rho = params.rho ?? 28;
  const beta = params.beta ?? (8 / 3);
  const dt = Math.max(0.0005, Math.min(0.1, params.dt ?? 0.01));
  const N = Math.max(100, Math.min(5000, (params.steps | 0) || 3000));
  let x = 1, y = 1, z = 1;
  const out = [];
  for (let i = 0; i < N; i++) {
    const dx = sigma * (y - x);
    const dy = x * (rho - z) - y;
    const dz = x * y - beta * z;
    x += dx * dt;
    y += dy * dt;
    z += dz * dt;
    out.push({ t: i * dt, x, y, z });
  }
  return out;
}

export default function(params) {
  const W = Math.max(24, Math.min(96, (params.size | 0) || 64));
  const H = W;
  const G = Math.max(20, Math.min(500, (params.generations | 0) || 200));
  const density = Math.max(0.05, Math.min(0.7, params.density ?? 0.32));
  let rng = ((params.seed | 0) || 42) >>> 0;
  const rand = () => { rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0; return rng / 4294967296; };
  let grid = new Uint8Array(W * H);
  for (let i = 0; i < grid.length; i++) grid[i] = rand() < density ? 1 : 0;
  const out = [];
  for (let g = 0; g < G; g++) {
    let alive = 0;
    for (let i = 0; i < grid.length; i++) alive += grid[i];
    out.push({ generation: g, population: alive, fraction: alive / grid.length });
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      const ym = (y - 1 + H) % H, yp = (y + 1) % H;
      for (let x = 0; x < W; x++) {
        const xm = (x - 1 + W) % W, xp = (x + 1) % W;
        const n = grid[ym * W + xm] + grid[ym * W + x] + grid[ym * W + xp]
                + grid[y  * W + xm] +                   grid[y  * W + xp]
                + grid[yp * W + xm] + grid[yp * W + x] + grid[yp * W + xp];
        const cell = grid[y * W + x];
        next[y * W + x] = cell ? ((n === 2 || n === 3) ? 1 : 0) : (n === 3 ? 1 : 0);
      }
    }
    grid = next;
  }
  return out;
}

export default function(params) {
  const I = params.I_inj ?? 10;
  const T = Math.max(10, Math.min(100, params.T ?? 50));
  const dt = Math.max(0.005, Math.min(0.05, params.dt ?? 0.01));
  const N = Math.floor(T / dt);
  const Cm = 1.0;
  const gNa = params.gNa ?? 120;
  const gK = params.gK ?? 36;
  const gL = 0.3;
  const ENa = 50, EK = -77, EL = -54.4;
  let V = -65, m = 0.05, h = 0.6, n = 0.32;
  const safe = (v, fn) => (Math.abs(v) < 1e-7 ? fn(1e-7) : fn(v));
  const am = (V) => safe(V + 40, (d) => 0.1 * d / (1 - Math.exp(-d / 10)));
  const bm = (V) => 4 * Math.exp(-(V + 65) / 18);
  const ah = (V) => 0.07 * Math.exp(-(V + 65) / 20);
  const bh = (V) => 1 / (1 + Math.exp(-(V + 35) / 10));
  const an = (V) => safe(V + 55, (d) => 0.01 * d / (1 - Math.exp(-d / 10)));
  const bn = (V) => 0.125 * Math.exp(-(V + 65) / 80);
  const stride = Math.max(1, Math.floor(N / 1500));
  const out = [];
  for (let i = 0; i < N; i++) {
    const aM = am(V), bM = bm(V);
    const aH = ah(V), bH = bh(V);
    const aN = an(V), bN = bn(V);
    m += dt * (aM * (1 - m) - bM * m);
    h += dt * (aH * (1 - h) - bH * h);
    n += dt * (aN * (1 - n) - bN * n);
    const INa = gNa * m * m * m * h * (V - ENa);
    const IK = gK * n * n * n * n * (V - EK);
    const IL = gL * (V - EL);
    V += dt * (I - INa - IK - IL) / Cm;
    if (i % stride === 0) out.push({ t: i * dt, V, m, h, n });
  }
  return out;
}

export default function(params) {
  const lr = Math.max(0.001, Math.min(0.5, params.lr ?? 0.05));
  const beta1 = Math.max(0.5, Math.min(0.9999, params.beta1 ?? 0.9));
  const beta2 = Math.max(0.5, Math.min(0.99999, params.beta2 ?? 0.999));
  const eps = 1e-8;
  const T = Math.max(20, Math.min(500, (params.T | 0) || 200));
  const f = (x, y) => (1 - x) * (1 - x) + 100 * (y - x * x) * (y - x * x);
  const grad = (x, y) => [
    -2 * (1 - x) - 400 * x * (y - x * x),
    200 * (y - x * x),
  ];
  let xA = params.x0 ?? -1.5, yA = params.y0 ?? 2.0;
  let mAx = 0, mAy = 0, vAx = 0, vAy = 0;
  let xS = xA, yS = yA;
  const lrSGD = lr * 0.4;
  const out = [];
  for (let t = 1; t <= T; t++) {
    const [gAx, gAy] = grad(xA, yA);
    mAx = beta1 * mAx + (1 - beta1) * gAx;
    mAy = beta1 * mAy + (1 - beta1) * gAy;
    vAx = beta2 * vAx + (1 - beta2) * gAx * gAx;
    vAy = beta2 * vAy + (1 - beta2) * gAy * gAy;
    const mhX = mAx / (1 - Math.pow(beta1, t));
    const mhY = mAy / (1 - Math.pow(beta1, t));
    const vhX = vAx / (1 - Math.pow(beta2, t));
    const vhY = vAy / (1 - Math.pow(beta2, t));
    xA -= lr * mhX / (Math.sqrt(vhX) + eps);
    yA -= lr * mhY / (Math.sqrt(vhY) + eps);
    const [gSx, gSy] = grad(xS, yS);
    xS -= lrSGD * gSx;
    yS -= lrSGD * gSy;
    out.push({ t, adam_loss: f(xA, yA), sgd_loss: f(xS, yS) });
  }
  return out;
}

export default function(params) {
  const k = Math.max(0.05, Math.min(20, params.k ?? 1));
  const dt = Math.max(0.001, Math.min(0.25, params.dt ?? 0.05));
  const T = Math.max(50, Math.min(2000, (params.T | 0) || 800));
  const x0 = params.x0 ?? 1;
  let xV = x0, vV = 0, aV = -k * xV;
  let xE = x0, vE = 0;
  const energy = (x, v) => 0.5 * v * v + 0.5 * k * x * x;
  const out = [{ t: 0, verlet_E: energy(xV, vV), euler_E: energy(xE, vE) }];
  for (let i = 1; i <= T; i++) {
    const xNew = xV + vV * dt + 0.5 * aV * dt * dt;
    const aNew = -k * xNew;
    const vNew = vV + 0.5 * (aV + aNew) * dt;
    xV = xNew; vV = vNew; aV = aNew;
    const aE = -k * xE;
    xE += vE * dt;
    vE += aE * dt;
    out.push({ t: i * dt, verlet_E: energy(xV, vV), euler_E: energy(xE, vE) });
  }
  return out;
}

export default function(params) {
  const W = 48, H = 48;
  const Du = Math.max(0.01, params.Du ?? 0.16);
  const Dv = Math.max(0.01, params.Dv ?? 0.08);
  const F = Math.max(0.001, params.F ?? 0.04);
  const k = Math.max(0.001, params.k ?? 0.06);
  const T = Math.max(60, Math.min(500, (params.T | 0) || 240));
  let u = new Float32Array(W * H);
  let v = new Float32Array(W * H);
  for (let i = 0; i < u.length; i++) { u[i] = 1; v[i] = 0; }
  const cx = (W / 2) | 0, cy = (H / 2) | 0;
  for (let dy = -3; dy <= 3; dy++) {
    for (let dx = -3; dx <= 3; dx++) {
      const idx = (cy + dy) * W + (cx + dx);
      u[idx] = 0.5; v[idx] = 0.25;
    }
  }
  const out = [];
  const un = new Float32Array(W * H);
  const vn = new Float32Array(W * H);
  for (let t = 0; t < T; t++) {
    for (let y = 0; y < H; y++) {
      const ym = (y - 1 + H) % H, yp = (y + 1) % H;
      for (let x = 0; x < W; x++) {
        const xm = (x - 1 + W) % W, xp = (x + 1) % W;
        const i = y * W + x;
        const lu = u[ym * W + x] + u[yp * W + x] + u[y * W + xm] + u[y * W + xp] - 4 * u[i];
        const lv = v[ym * W + x] + v[yp * W + x] + v[y * W + xm] + v[y * W + xp] - 4 * v[i];
        const uvv = u[i] * v[i] * v[i];
        un[i] = u[i] + Du * lu - uvv + F * (1 - u[i]);
        vn[i] = v[i] + Dv * lv + uvv - (F + k) * v[i];
      }
    }
    u.set(un); v.set(vn);
    let mu = 0, mv = 0;
    for (let i = 0; i < u.length; i++) { mu += u[i]; mv += v[i]; }
    mu /= u.length; mv /= v.length;
    let sv = 0;
    for (let i = 0; i < u.length; i++) { const d = v[i] - mv; sv += d * d; }
    out.push({ t, u_mean: mu, v_mean: mv, v_variance: sv / u.length });
  }
  return out;
}

export default function(params) {
  const N = Math.max(16, Math.min(96, (params.N | 0) || 48));
  const P = Math.max(1, Math.min(8, (params.P | 0) || 3));
  const T = Math.max(5, Math.min(200, (params.T | 0) || 60));
  const noise = Math.max(0, Math.min(0.5, params.noise ?? 0.3));
  let rng = ((params.seed | 0) || 7) >>> 0;
  const rand = () => { rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0; return rng / 4294967296; };
  const sgn = (x) => (x >= 0 ? 1 : -1);
  const patterns = [];
  for (let p = 0; p < P; p++) {
    const v = new Int8Array(N);
    for (let i = 0; i < N; i++) v[i] = rand() < 0.5 ? -1 : 1;
    patterns.push(v);
  }
  const W = new Float32Array(N * N);
  for (let p = 0; p < P; p++) {
    const v = patterns[p];
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        if (i !== j) W[i * N + j] += v[i] * v[j];
      }
    }
  }
  for (let i = 0; i < W.length; i++) W[i] /= N;
  const s = new Int8Array(N);
  for (let i = 0; i < N; i++) s[i] = patterns[0][i];
  const flips = Math.floor(N * noise);
  for (let f = 0; f < flips; f++) {
    const idx = Math.floor(rand() * N);
    s[idx] = -s[idx];
  }
  const energy = () => {
    let e = 0;
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) e -= W[i * N + j] * s[i] * s[j];
    }
    return e / 2;
  };
  const overlapWith = (p) => {
    let o = 0;
    for (let i = 0; i < N; i++) o += s[i] * patterns[p][i];
    return o / N;
  };
  const out = [{ step: 0, energy: energy(), overlap: overlapWith(0) }];
  for (let t = 1; t <= T; t++) {
    for (let k = 0; k < N; k++) {
      const i = Math.floor(rand() * N);
      let h = 0;
      for (let j = 0; j < N; j++) h += W[i * N + j] * s[j];
      s[i] = sgn(h);
    }
    out.push({ step: t, energy: energy(), overlap: overlapWith(0) });
  }
  return out;
}

export default function(params) {
  const r = Math.max(0.5, Math.min(4, params.r ?? 3.7));
  const N = Math.max(50, Math.min(2000, (params.N | 0) || 500));
  const transient = Math.max(0, Math.min(2000, (params.transient | 0) || 200));
  let x = Math.max(0.001, Math.min(0.999, params.x0 ?? 0.5));
  for (let i = 0; i < transient; i++) x = r * x * (1 - x);
  const out = [];
  for (let i = 0; i < N; i++) {
    x = r * x * (1 - x);
    out.push({ n: i, x });
  }
  return out;
}

export default function(params) {
  const W = Math.max(41, Math.min(121, (params.size | 0) || 81)) | 1;
  const H = W;
  const cx = (W / 2) | 0, cy = (H / 2) | 0;
  const N = Math.max(30, Math.min(600, (params.N | 0) || 250));
  let rng = ((params.seed | 0) || 11) >>> 0;
  const rand = () => { rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0; return rng / 4294967296; };
  const occupied = new Uint8Array(W * H);
  occupied[cy * W + cx] = 1;
  let maxR = 0;
  const out = [{ particle: 0, max_radius: 0, log_radius: 0, log_count: 0 }];
  for (let p = 1; p <= N; p++) {
    const r0 = Math.min(W / 2 - 2, maxR + 4);
    const theta = rand() * 2 * Math.PI;
    let px = Math.round(cx + r0 * Math.cos(theta));
    let py = Math.round(cy + r0 * Math.sin(theta));
    let stuck = false;
    let steps = 0;
    const maxSteps = 4000;
    while (!stuck && steps < maxSteps) {
      for (let dy = -1; dy <= 1 && !stuck; dy++) {
        for (let dx = -1; dx <= 1 && !stuck; dx++) {
          if (dx === 0 && dy === 0) continue;
          const nx = px + dx, ny = py + dy;
          if (nx >= 0 && nx < W && ny >= 0 && ny < H && occupied[ny * W + nx]) {
            stuck = true;
          }
        }
      }
      if (stuck) break;
      const m = rand();
      if (m < 0.25) px++; else if (m < 0.5) px--; else if (m < 0.75) py++; else py--;
      if (px < 1) px = 1; if (px >= W - 1) px = W - 2;
      if (py < 1) py = 1; if (py >= H - 1) py = H - 2;
      steps++;
    }
    if (stuck && px > 0 && px < W - 1 && py > 0 && py < H - 1) {
      occupied[py * W + px] = 1;
      const dx = px - cx, dy = py - cy;
      const r = Math.sqrt(dx * dx + dy * dy);
      if (r > maxR) maxR = r;
      out.push({ particle: p, max_radius: maxR, log_radius: Math.log10(Math.max(0.01, maxR)), log_count: Math.log10(p) });
    }
  }
  return out;
}

export default function(params) {
  const popSize = Math.max(10, Math.min(100, (params.pop | 0) || 40));
  const G = Math.max(10, Math.min(250, (params.G | 0) || 100));
  const mutationRate = Math.max(0, Math.min(0.8, params.mutationRate ?? 0.15));
  const sigma = Math.max(0.01, Math.min(2.5, params.mutationSigma ?? 0.5));
  let rng = ((params.seed | 0) || 5) >>> 0;
  const rand = () => { rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0; return rng / 4294967296; };
  const gauss = () => {
    const u = Math.max(1e-9, rand()), v = rand();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const fitness = (x) => Math.exp(-((x - 2) * (x - 2)) / 0.5)
    + 1.5 * Math.exp(-((x - 5) * (x - 5)) / 0.3)
    + 0.8 * Math.exp(-((x - 8) * (x - 8)) / 0.4);
  let pop = new Array(popSize);
  for (let i = 0; i < popSize; i++) pop[i] = rand() * 10;
  const out = [];
  for (let g = 0; g < G; g++) {
    const fits = pop.map(fitness);
    let best = -Infinity, sum = 0;
    for (let i = 0; i < popSize; i++) { if (fits[i] > best) best = fits[i]; sum += fits[i]; }
    out.push({ g, best, mean: sum / popSize });
    const next = new Array(popSize);
    for (let i = 0; i < popSize; i++) {
      const a = Math.floor(rand() * popSize), b = Math.floor(rand() * popSize);
      let parent = fits[a] > fits[b] ? pop[a] : pop[b];
      if (rand() < 0.5) {
        const c = Math.floor(rand() * popSize);
        const alpha = rand();
        parent = alpha * parent + (1 - alpha) * pop[c];
      }
      if (rand() < mutationRate) parent += sigma * gauss();
      if (parent < 0) parent = 0; if (parent > 10) parent = 10;
      next[i] = parent;
    }
    pop = next;
  }
  return out;
}

export default function(params) {
  const target = Math.max(1e-6, params.target ?? 2);
  const x0 = Math.max(1e-6, params.x0 ?? 2);
  const maxIter = Math.max(3, Math.min(80, (params.maxIter | 0) || 30));
  const tol = 1e-15;
  const f = (x) => x * x - target;
  const df = (x) => 2 * x;
  let x = x0;
  const initialErr = Math.abs(x * x - target);
  const out = [{ iter: 0, x, error: initialErr, log_error: Math.log10(initialErr + 1e-30) }];
  for (let i = 1; i <= maxIter; i++) {
    const denom = df(x);
    if (Math.abs(denom) < 1e-16) break;
    x = x - f(x) / denom;
    const err = Math.abs(x * x - target);
    out.push({ iter: i, x, error: err, log_error: Math.log10(err + 1e-30) });
    if (err < tol) break;
  }
  return out;
}

export default function(params) {
  const N = Math.max(1, Math.min(50, (params.harmonics | 0) || 8));
  const samples = Math.max(50, Math.min(1000, (params.samples | 0) || 400));
  const out = [];
  for (let i = 0; i < samples; i++) {
    const t = (i / samples) * 2;
    let approx = 0;
    for (let k = 1; k <= N; k++) {
      const n = 2 * k - 1;
      approx += Math.sin(2 * Math.PI * n * t) / n;
    }
    approx *= 4 / Math.PI;
    const sin = Math.sin(2 * Math.PI * t);
    const target = sin > 0 ? 1 : (sin < 0 ? -1 : 0);
    out.push({ t, approx, target, residual: approx - target });
  }
  return out;
}
